pdfjsLib.GlobalWorkerOptions.workerSrc='vendor/pdf.worker.min.js';
const $=id=>document.getElementById(id),settings={high:{dpi:200,q:.86},balanced:{dpi:150,q:.68},small:{dpi:96,q:.45}};
let doc=null,file=null,level='balanced',busy=false,cancelled=false,url=null,previewVersion=0;
const size=n=>n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(2)+' MB';
function status(s){$('status').textContent=s}
function clearResult(){if(url)URL.revokeObjectURL(url);url=null;$('result').hidden=true}
async function raster(page){const base=page.getViewport({scale:1}),s=settings[level];let scale=s.dpi/72;scale=Math.min(scale,Math.sqrt(16000000/(base.width*base.height)));const view=page.getViewport({scale}),c=document.createElement('canvas');c.width=Math.ceil(view.width);c.height=Math.ceil(view.height);const ctx=c.getContext('2d',{willReadFrequently:$('gray').checked});await page.render({canvasContext:ctx,viewport:view,background:'#ffffff'}).promise;if($('gray').checked){const data=ctx.getImageData(0,0,c.width,c.height);for(let i=0;i<data.data.length;i+=4){const g=Math.round(.299*data.data[i]+.587*data.data[i+1]+.114*data.data[i+2]);data.data[i]=data.data[i+1]=data.data[i+2]=g}ctx.putImageData(data,0,0)}const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',s.q));c.width=0;c.height=0;if(!blob)throw Error('画像の変換に失敗しました。');return{bytes:new Uint8Array(await blob.arrayBuffer()),width:base.width,height:base.height}}
async function preview(){if(!doc||busy)return;const version=++previewVersion;try{const page=await doc.getPage(1),r=await raster(page);if(version!==previewVersion)return;const blob=new Blob([r.bytes],{type:'image/jpeg'}),img=await createImageBitmap(blob),c=$('preview');c.width=img.width;c.height=img.height;c.getContext('2d').drawImage(img,0,0);img.close();$('emptyPreview').hidden=true;c.hidden=false;$('previewlabel').textContent=settings[level].dpi+' dpi · 1ページ目'}catch(e){status('プレビューを表示できませんでした。'+e.message)}}
async function load(f){if(busy||!f)return;if(!/\.pdf$/i.test(f.name)){status('PDFファイルを選択してください。');return}if(f.size>200*1048576){status('200 MB以下のPDFを選択してください。');return}clearResult();status('PDFを読み込んでいます…');try{const bytes=new Uint8Array(await f.arrayBuffer());if(doc)await doc.destroy();doc=null;const task=pdfjsLib.getDocument({data:bytes,isEvalSupported:false});task.onPassword=()=>task.destroy();doc=await task.promise;file=f;$('drop').hidden=true;$('loaded').hidden=false;$('filename').textContent=f.name;$('filemeta').textContent=size(f.size)+' · '+doc.numPages+'ページ';status('');await preview()}catch(e){doc=null;file=null;$('drop').hidden=false;$('loaded').hidden=true;$('preview').hidden=true;$('emptyPreview').hidden=false;status('PDFを読み込めませんでした。パスワード付きの場合は解除したPDFをご利用ください。')}}
$('choose').onclick=()=>$('file').click();$('file').onchange=e=>load(e.target.files[0]);$('reset').onclick=()=>{if(!busy)$('file').click()};
for(const name of ['dragenter','dragover'])$('drop').addEventListener(name,e=>{e.preventDefault();$('drop').classList.add('drag')});for(const name of ['dragleave','drop'])$('drop').addEventListener(name,e=>{e.preventDefault();$('drop').classList.remove('drag');if(name==='drop')load(e.dataTransfer.files[0])});
document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(busy)return;level=b.dataset.level;document.querySelectorAll('[data-level]').forEach(x=>x.classList.toggle('selected',x===b));clearResult();preview()});$('gray').onchange=()=>{clearResult();preview()};$('cancel').onclick=()=>{cancelled=true;status('現在のページの処理後に停止します…')};
$('compress').onclick=async()=>{if(!doc||busy)return;busy=true;cancelled=false;previewVersion++;clearResult();$('compress').disabled=true;$('gray').disabled=true;$('reset').disabled=true;$('cancel').hidden=false;$('progress').hidden=false;$('progress').value=0;try{const out=await PDFLib.PDFDocument.create();for(let i=1;i<=doc.numPages;i++){if(cancelled)throw Error('処理をキャンセルしました。');status(i+' / '+doc.numPages+'ページを圧縮中…');await new Promise(r=>setTimeout(r,0));const page=await doc.getPage(i),r=await raster(page);if(cancelled)throw Error('処理をキャンセルしました。');const jpg=await out.embedJpg(r.bytes);out.addPage([r.width,r.height]).drawImage(jpg,{x:0,y:0,width:r.width,height:r.height});page.cleanup();$('progress').value=i/doc.numPages*100}status('PDFを保存しています…');const bytes=await out.save();if(cancelled)throw Error('処理をキャンセルしました。');const smaller=bytes.length<file.size;const blob=smaller?new Blob([bytes],{type:'application/pdf'}):file;url=URL.createObjectURL(blob);$('download').href=url;$('download').download=smaller?file.name.replace(/\.pdf$/i,'_compressed.pdf'):file.name;$('before').textContent=size(file.size);$('after').textContent=size(blob.size);$('reduction').textContent=smaller?'−'+Math.round((1-blob.size/file.size)*100)+'%':'0%';$('resultnote').textContent=smaller?'ページ数と用紙サイズを保って圧縮しました。保存前に文字の読みやすさをご確認ください。':'この設定では元のファイルより小さくなりませんでした。元のPDFをダウンロードできます。「最小サイズ」もお試しください。';$('result').hidden=false;status('')}catch(e){status(e.message||'圧縮に失敗しました。より小さなPDFでお試しください。')}finally{busy=false;$('compress').disabled=false;$('gray').disabled=false;$('reset').disabled=false;$('cancel').hidden=true;$('progress').hidden=true}};
